          </div>
        </div>
      </header>
      <main className="mx-auto max-w-3xl px-6 pt-4 pb-40">
        <EditorPane
          initialDoc={initialDoc}
          onChange={onDocumentChange}
          onNotice={onNotice}
          onReviewStatus={setReview}
          onReviewNotice={onReviewNotice}
          onReviewControls={setControls}
          getTopInset={getTopInset}
        />
      </main>
